window.__votdWeek && window.__votdWeek({"week":"2026-10-12","reading":"Isaiah 58–66","days":[{"d":"2026-10-12","ref":"Isaiah 58:1","b":"Isaiah","c":58,"v":1,"he":"קְרָא בְגָרוֹן אַל־תַּחְשֹׂךְ כַּשּׁוֹפָר הָרֵם קוֹלֶךָ וְהַגֵּד לְעַמִּי פִּשְׁעָם וּלְבֵית יַעֲקֹב חַטֹּאתָם׃","en":"Cry aloud, spare not, lift up thy voice like a trumpet, and shew my people their transgression, and the house of Jacob their sins."},{"d":"2026-10-13","ref":"Isaiah 59:16","b":"Isaiah","c":59,"v":16,"he":"וַיַּרְא כִּי־אֵין אִישׁ וַיִּשְׁתּוֹמֵם כִּי אֵין מַפְגִּיעַ וַתּוֹשַׁע־לוֹ זְרֹעוֹ וְצִדְקָתוֹ הִיא סְמָכָתְהוּ׃","en":"And he saw that there was no man, and wondered that there was no intercessor: therefore his arm brought salvation unto him; and his righteousness, it sustained him."},{"d":"2026-10-14","ref":"Isaiah 59:18","b":"Isaiah","c":59,"v":18,"he":"כְּעַל גְּמֻלוֹת כְּעַל יְשַׁלֵּם חֵמָה לְצָרָיו גְּמוּל לְאֹיְבָיו לָאִיִּים גְּמוּל יְשַׁלֵּם׃","en":"According to their deeds, accordingly he will repay, fury to his adversaries, recompence to his enemies; to the islands he will repay recompence."},{"d":"2026-10-15","ref":"Isaiah 63:3","b":"Isaiah","c":63,"v":3,"he":"פּוּרָה דָּרַכְתִּי לְבַדִּי וּמֵעַמִּים אֵין־אִישׁ אִתִּי וְאֶדְרְכֵם בְּאַפִּי וְאֶרְמְסֵם בַּחֲמָתִי וְיֵז נִצְחָם עַל־בְּגָדַי וְכׇל־מַלְבּוּשַׁי אֶגְאָלְתִּי׃","en":"I have trodden the winepress alone; and of the people there was none with me: for I will tread them in mine anger, and trample them in my fury; and their blood shall be sprinkled upon my garments, and I will stain all my raiment."},{"d":"2026-10-16","ref":"Isaiah 63:9","b":"Isaiah","c":63,"v":9,"he":"בְּכׇל־צָרָתָם לוֹ צָר וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם בְּאַהֲבָתוֹ וּבְחֶמְלָתוֹ הוּא גְאָלָם וַיְנַטְּלֵם וַיְנַשְּׂאֵם כׇּל־יְמֵי עוֹלָם׃","en":"In all their affliction he was afflicted, and the angel of his presence saved them: in his love and in his pity he redeemed them; and he bare them, and carried them all the days of old."},{"d":"2026-10-17","ref":"Isaiah 64:4","b":"Isaiah","c":64,"v":3,"he":"וּמֵעוֹלָם לֹא־שָׁמְעוּ לֹא הֶאֱזִינוּ עַיִן לֹא־רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה־לוֹ׃","en":"For since the beginning of the world men have not heard, nor perceived by the ear, neither hath the eye seen, O God, beside thee, what he hath prepared for him that waiteth for him."},{"d":"2026-10-18","ref":"Isaiah 66:15","b":"Isaiah","c":66,"v":15,"he":"כִּי־הִנֵּה יְהֹוָה בָּאֵשׁ יָבוֹא וְכַסּוּפָה מַרְכְּבֹתָיו לְהָשִׁיב בְּחֵמָה אַפּוֹ וְגַעֲרָתוֹ בְּלַהֲבֵי־אֵשׁ׃","en":"For, behold, the LORD will come with fire, and with his chariots like a whirlwind, to render his anger with fury, and his rebuke with flames of fire."}]});
